mapper.select:
SELECT e.id, e.plate_no AS plateNo, e.plate_color AS plateColor, e.space_no AS spaceNo, e.enter_time AS enterTime, e.record_type AS recordType, e.status AS status, s.name AS stationName, e.remark, e.proof_image AS proofImage, e.is_corrected AS isCorrected, e.reserve1, e.reserve2, e.creator, e.updater, e.create_time AS createTime, e.update_time AS updateTime FROM enter_record e LEFT JOIN station_info s ON e.station_id = s.id WHERE e.deleted = 0
AND e.plate_no LIKE CONCAT('%', #{query.plateNo}, '%')
AND e.plate_color = #{query.plateColor}
AND e.space_no LIKE CONCAT('%', #{query.spaceNo}, '%')
AND e.enter_time BETWEEN #{query.enterTime[0]} AND #{query.enterTime[1]}
AND e.record_type = #{query.recordType}
AND e.status = #{query.status}
AND e.station_id = #{query.stationId}
AND e.remark LIKE CONCAT('%', #{query.remark}, '%')
AND e.is_corrected = #{query.isCorrected}
ORDER BY e.id DESC
